Author: pancake <pancake@nopcode.org>
Date:   Fri Jan 7 00:24:18 2022 +0100

    fix insn initialization when instruction have no operands or have a prefix

diff --git a/cs.c b/cs.c
index 786922b4..db75c756 100644
--- a/cs.c
+++ b/cs.c
@@ -540,6 +540,7 @@ static void fill_insn(struct cs_struct *handle, cs_insn *insn, char *buffer, MCI
        // fill the instruction bytes.
        // we might skip some redundant bytes in front in the case of X86
        memcpy(insn->bytes, code + insn->size - copy_size, copy_size);
+       insn->op_str[0] = '\0';
        insn->size = copy_size;

        // alias instruction might have ID saved in OpcodePub
@@ -551,6 +552,10 @@ static void fill_insn(struct cs_struct *handle, cs_insn *insn, char *buffer, MCI
                postprinter((csh)handle, insn, buffer, mci);

 #ifndef CAPSTONE_DIET
+       char *prefix = strchr (buffer, '|');
+       if (prefix) {
+               *prefix = ' ';
+       }
        char *tab = strchr (buffer, '\t');
        if (tab) {
                *tab = 0;
commit 18b504b33f1742fd3b0e539a6b7b7a30d9cbe37c
Author: Connor Rigby <connorr@hey.com>
Date:   Mon Jun 26 10:14:58 2023 -0600

    use calloc for cs_insn instead of malloc (#1972)

    Signed-off-by: Connor Rigby <connorr@hey.com>

diff --git a/cs.c b/cs.c
index 1b7ba05f..6f37b26b 100644
--- a/cs.c
+++ b/cs.c
@@ -586,6 +586,7 @@ static void fill_insn(struct cs_struct *handle, cs_insn *insn, char *buffer, MCI

 #ifndef CAPSTONE_DIET
        mnem = insn->mnemonic;
+       // memset(mnem, 0, CS_MNEMONIC_SIZE);
        for (sp = buffer; *sp; sp++) {
                if (*sp == ' '|| *sp == '\t')
                        break;
@@ -896,7 +897,7 @@ size_t CAPSTONE_API cs_disasm(csh ud, const uint8_t *buffer, size_t size, uint64
        size_org = size;

        total_size = sizeof(cs_insn) * cache_size;
-       total = cs_mem_malloc(total_size);
+       total = cs_mem_calloc(sizeof(cs_insn), cache_size);
        if (total == NULL) {
                // insufficient memory
                handle->errnum = CS_ERR_MEM;
